'use strict';
const menu=document.querySelector('.menu-toggle'),navigation=document.querySelector('#navigation');
menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));navigation.classList.toggle('open',!expanded)});
navigation.addEventListener('click',e=>{if(e.target.closest('a')){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&navigation.classList.contains('open')){menu.setAttribute('aria-expanded','false');navigation.classList.remove('open');menu.focus()}});
const goals=[['No poverty','#e5243b','Build a world where everyone can meet their basic needs.'],['Zero hunger','#dda63a','Connect food security, nutrition and sustainable agriculture.'],['Good health and well-being','#4c9f38','Support healthier lives at every age.'],['Quality education','#c5192d','Expand access to inclusive learning and opportunity.'],['Gender equality','#ff3a21','Advance equal rights and opportunities for women and girls.'],['Clean water and sanitation','#26bde2','Make safe water and sanitation accessible to all.'],['Affordable and clean energy','#fcc30b','Accelerate access to reliable, sustainable energy.'],['Decent work and economic growth','#a21942','Create opportunity through inclusive economies and decent work.'],['Industry, innovation and infrastructure','#fd6925','Strengthen the systems that help communities thrive.'],['Reduced inequalities','#dd1367','Close gaps in opportunity within and between countries.'],['Sustainable cities and communities','#fd9d24','Make communities more inclusive, resilient and sustainable.'],['Responsible consumption and production','#bf8b2e','Use resources thoughtfully across the way we make and consume.'],['Climate action','#3f7e44','Respond to climate change through practical local action.'],['Life below water','#0a97d9','Protect marine ecosystems and the lives they sustain.'],['Life on land','#56c02b','Restore ecosystems and protect biodiversity.'],['Peace, justice and strong institutions','#00689d','Support peaceful societies, justice and accountable institutions.'],['Partnerships for the goals','#19486a','Connect people, knowledge and resources to move forward together.']];
const goalGrid=document.querySelector('#goal-grid');
goals.forEach(([name,color],i)=>{const b=document.createElement('button');b.className='goal-button';b.style.setProperty('--goal-color',color);b.setAttribute('aria-label',`Goal ${i+1}: ${name}`);b.setAttribute('aria-pressed',String(i===0));b.innerHTML=`<span class="num">${i+1}</span><span class="name">${name}</span>`;b.addEventListener('click',()=>selectGoal(i));goalGrid.append(b)});
function selectGoal(i){const [name,color,description]=goals[i];goalGrid.querySelectorAll('button').forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));document.querySelector('#goal-number').textContent=String(i+1).padStart(2,'0');document.querySelector('.goal-detail').style.setProperty('--goal-color',color);document.querySelector('#goal-title').textContent=name;document.querySelector('#goal-description').textContent=description;const a=document.querySelector('#goal-link');a.href=`https://sdgs.un.org/goals/goal${i+1}`;a.textContent=`Explore Goal ${i+1} at the UN ↗`}
selectGoal(0);
const platforms={map:{url:'https://globalactionmosaic.ushahidi.io/map',name:'interactive map',title:'A world of action,\nwaiting to be explored.',description:'Open the interactive map to discover projects by location. The illustration behind this panel is not live project data.'},dashboard:{url:'https://gam-dashboard.github.io/dashboard/#/',name:'impact dashboard',title:'A different lens\non local impact.',description:'Explore the GAM dashboard in its own interactive view. Availability and displayed information are managed by the GAM platform.'}};
let selectedPlatform='map',loadVersion=0,embedTimer;
const embed=document.querySelector('#embed-container'),preview=document.querySelector('#platform-preview'),load=document.querySelector('#load-platform'),status=document.querySelector('#embed-status');
document.querySelectorAll('[data-platform]').forEach(b=>b.addEventListener('click',()=>{selectedPlatform=b.dataset.platform;loadVersion++;clearTimeout(embedTimer);document.querySelectorAll('[data-platform]').forEach(x=>{const active=x===b;x.classList.toggle('selected',active);x.setAttribute('aria-pressed',String(active))});const p=platforms[selectedPlatform];embed.replaceChildren();embed.hidden=true;preview.hidden=false;document.querySelector('#platform-label').textContent=`GLOBAL ACTION MOSAIC / ${selectedPlatform.toUpperCase()}`;document.querySelector('#platform-title').textContent=p.title;document.querySelector('#platform-description').textContent=p.description;load.textContent=`Load ${p.name} ↗`;const a=document.querySelector('#platform-external');a.href=p.url;a.textContent=`Open full ${selectedPlatform} ↗`;status.textContent='Load the platform here, or explore it in a new tab.'}));
load.addEventListener('click',()=>{const p=platforms[selectedPlatform],version=++loadVersion;const frame=document.createElement('iframe');frame.title=`Global Action Mosaic ${p.name}`;frame.referrerPolicy='no-referrer';frame.src=p.url;frame.setAttribute('allowfullscreen','');embed.replaceChildren(frame);preview.hidden=true;embed.hidden=false;status.textContent='Loading external platform… Direct link is always available.';frame.addEventListener('load',()=>{if(version===loadVersion)status.textContent='External platform loaded. Blank or blocked? Open the full view instead.'});frame.addEventListener('error',()=>{if(version===loadVersion)status.textContent='Unable to load this view. Please use the direct link.'});clearTimeout(embedTimer);embedTimer=setTimeout(()=>{if(version===loadVersion)status.textContent='If the view is blank or unavailable, open the platform directly.'},10000)});
const recognitions=[{year:'2016',title:'Selected at the UN Solutions Summit',description:'One of ten innovations selected. Original reporting by Ushahidi.',url:'https://www.ushahidi.com/about/blog/two-ushahidi-deployers-selected-for-un-solutions-summit'},{year:'2021',title:'A chapter in the story of crowdsourcing',description:'Featured in Crowdsourcing, Constructing and Collaborating. Bloomsbury, 2021 PDF edition.',url:'https://www.bloomsbury.com/ca/crowdsourcing-constructing-and-collaborating-9789389812237/'},{year:'2025',title:'Global Action Mosaic at the UN',description:'Highlighted in the President of the General Assembly’s remarks at the Doha Civil Society Forum.',url:'https://www.un.org/pga/80/2025/11/05/pga-remarks-at-the-civil-society-forum-at-the-second-world-summit-for-social-development-doha/'},{year:'2026',title:'A commitment to community-powered data',description:'GAM’s commitment on the UN World Data Forum’s Commit to Data platform.',url:'https://commit-2-data.com/en/commitments/global-action-mosaic-turning-crowdsourced-sdg-data-into-actionable-insightsu2hnkz3qpm6ul4ykbvvlcgfi9z9bpsiiayzkxkip'}];
recognitions.forEach(r=>{const a=document.createElement('a');a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';a.innerHTML=`<span class="year">${r.year}</span><h3>${r.title}</h3><p>${r.description}</p><span class="arrow" aria-hidden="true">↗</span>`;document.querySelector('#timeline').append(a)});
const gallery=[{file:'community-1.jpg',id:'1S7LWkf3jvM89bD5YvdnIalv4v1Kg6veN',alt:'Humanitarian Tracker gathering in Damascus, August 2025'},{file:'community-2.jpg',id:'1snH8rewPLKbAL9DMjQCz4f9CZ0QtRRZx',alt:'Community members at the Damascus gathering, August 2025'},{file:'community-3.jpg',id:'1kBJ2qs8C7IqBAjanF5t1obxLXrmt8gvr',alt:'Participants connecting at the Damascus gathering, August 2025'}];
const lightbox=document.querySelector('#lightbox');let lastImageButton;
gallery.forEach(item=>{const b=document.createElement('button');b.setAttribute('aria-label',`Enlarge: ${item.alt}`);const img=document.createElement('img');img.src=`assets/${item.file}`;img.alt=item.alt;img.loading='lazy';img.width=1200;img.height=800;const arrow=document.createElement('span');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');b.append(img,arrow);b.addEventListener('click',()=>{lastImageButton=b;document.querySelector('#lightbox-image').src=img.src;document.querySelector('#lightbox-image').alt=item.alt;document.querySelector('#lightbox-caption').textContent=item.alt;document.querySelector('#lightbox-source').href=`https://drive.google.com/file/d/${item.id}/view`;lightbox.showModal()});document.querySelector('#gallery').append(b)});
document.querySelector('#close-lightbox').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});lightbox.addEventListener('close',()=>lastImageButton?.focus());

recognitions.forEach(r=>{const a=document.createElement('a');a.href=r.url;a.target='_blank';a.rel='noopener noreferrer';const title=document.createElement('span');title.textContent=`${r.year} · ${r.title}`;const detail=document.createElement('small');detail.textContent=r.description;const arrow=document.createElement('b');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');a.append(title,detail,arrow);document.querySelector('#archive-recognitions').append(a)});
